#!/usr/bin/env node
/**
 * AUTO-GENERATED by GateMaster — trae 原生 hook
 * Rule: 修复任何bug必须附带能复现该bug的回归测试
 * Rule Key: host-rule-a0d618cdfceb
 * Rule ID: 79921b50-72a9-491d-9d5a-7a5bd51086a2
 * Enforcement: must
 * Trae event: PreToolUse
 * Matcher: RunCommand
 *
 * 场景发散设计结论：
 * "修复任何 bug"包含：
 *   - commit 消息含 fix: → critical（必须含回归测试）
 *   - commit 消息含 fix(scope): → critical
 *   - commit 消息含 hotfix: → critical
 *   - commit 消息含 修复/bugfix/patch → critical
 *   - 其他类型 feat/refactor/docs → skip（R10 已覆盖）
 * "回归测试"包含：
 *   - *.test.ts, *.test.js, *.test.tsx, *.test.jsx, *.test.mjs
 *   - *.spec.ts, *.spec.js
 *   - test_*.py, *_test.py, *_test.go, *_test.rs
 *   - __tests__/ 目录下的文件
 *
 * shouldRun: git commit 命令且消息含 fix 关键词
 * run: 检查 staged diff 里是否有测试文件，没有则 REJECT
 */

import { execSync } from "child_process";
import { runHook, getCwd } from "./_lib.mjs";

const FIX_PATTERN = /\b(fix|hotfix|bugfix|patch)\b/i;

const TEST_FILE_PATTERNS = [
  /\.test\.(ts|js|tsx|jsx|mjs)$/i,
  /\.spec\.(ts|js|tsx|jsx)$/i,
  /test_.*\.py$/i,
  /.*_test\.py$/i,
  /.*_test\.go$/i,
  /.*_test\.rs$/i,
  /__tests__\//i,
];

function getCommand(context) {
  return context?.tool_input?.command
    || context?.tool_input?.cmd
    || context?.command
    || "";
}

function isGitCommit(command) {
  return /^git\s+commit\b/i.test(command.trim());
}

function extractCommitMessage(command) {
  const match = command.match(/-m\s+["']([^"']+)["']/);
  return match ? match[1] : "";
}

function shouldRun(context) {
  const command = getCommand(context);
  if (!isGitCommit(command)) return false;
  const msg = extractCommitMessage(command);
  if (!msg) return false;
  return FIX_PATTERN.test(msg);
}

function run(context) {
  const cwd = getCwd(context);

  let stagedFiles = "";
  try {
    stagedFiles = execSync("git diff --cached --name-only", { cwd, encoding: "utf-8", timeout: 5000 });
  } catch {
    return { action: "PASS", message: "无法获取 staged 文件列表，放行。" };
  }

  const files = stagedFiles.split(/\r?\n/).filter(f => f.trim());
  const hasTestFiles = files.some(f => TEST_FILE_PATTERNS.some(p => p.test(f)));

  if (!hasTestFiles) {
    return {
      action: "REJECT",
      reason: "修复 bug 但 diff 里没有回归测试。修复任何 bug 必须附带能复现该 bug 的回归测试。",
      suggestions: [
        "新增一个能复现该 bug 的测试用例",
        "测试文件命名: *.test.ts / *.spec.ts / test_*.py",
        "确保测试在修复前失败、修复后通过",
        "暂存测试文件: git add <test-file>",
      ]
    };
  }

  return { action: "PASS", message: "Bug 修复提交包含回归测试。" };
}

runHook(shouldRun, run, "PreToolUse");
